"""Starter configuration text used by `gpuctl init` and examples/config.toml."""

from __future__ import annotations


def render_config(gpus: list[dict], system: bool = False, nvidia_smi: str | None = None) -> str:
    lines = [
        "# resourced configuration. Generated by `gpuctl init`; edit as needed.",
        "# Restart the daemon after changing it (claims survive a restart).",
        "",
        "[daemon]",
    ]
    if system:
        lines += [
            '# Shared install: let this group use the socket (the service account is added to it).',
            '# socket_group = "gpuusers"',
        ]
    else:
        lines += ['# runtime_dir = "/path"   # default: $XDG_RUNTIME_DIR/resourced']
    lines += [
        "sample_interval = 30   # seconds between resource samples",
        "probe_timeout = 10     # seconds before a probe (nvidia-smi, disk) counts as failed",
        f'nvidia_smi = "{nvidia_smi}"' if nvidia_smi else '# nvidia_smi = "nvidia-smi"',
        "",
        "# GPUs managed by resourced. The UUID is authoritative; alias and index are for convenience.",
    ]
    for i, gpu in enumerate(gpus):
        index = gpu.get("index") if gpu.get("index") is not None else i
        lines += [
            "",
            f"# {gpu.get('name') or 'GPU'}",
            "[[gpu]]",
            f'uuid = "{gpu["uuid"]}"',
            f'alias = "gpu{index}"',
            f"index = {index}",
        ]
    lines += [
        "",
        "# Advisory resource limits. Tasks should follow them; resourced never blocks or kills anything.",
        "# Limits are inclusive: free space <= warn/stop value, or used % >= value, reaches that level.",
        "# Keys: warn_free_gib stop_free_gib warn_free_pct stop_free_pct warn_used_pct stop_used_pct",
        "#",
        "# [[check]]",
        '# name = "ram"',
        '# type = "ram"          # MemAvailable',
        "# warn_free_pct = 15",
        "# stop_free_pct = 10",
        "#",
        "# [[check]]",
        '# name = "data"',
        '# type = "disk"',
        '# path = "/data"',
        "# warn_free_pct = 20",
        "# stop_free_pct = 10",
        "#",
        "# [[check]]",
        '# name = "tmp"',
        '# type = "disk"',
        '# path = "/tmp"',
        "# warn_used_pct = 80",
        "# stop_used_pct = 90",
        "",
    ]
    return "\n".join(lines)
